import { Link, useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { productApi } from '../services/api';
import ProductCard from '../components/ProductCard';
import './Home.css';

const quickSearches = ['iPhone 17 Pro Max', 'Samsung Galaxy S26', 'RTX 5090', 'MacBook Pro M5', 'PlayStation 6'];

function Home() {
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [trending, setTrending] = useState([]);
  const [providerStatus, setProviderStatus] = useState(null);

  useEffect(() => {
    productApi.getTrending(8).then((data) => setTrending(data.products || [])).catch(() => setTrending([]));
    productApi.getProviderStatus().then((data) => setProviderStatus(data.providers)).catch(() => null);
  }, []);

  const submit = (event) => {
    event.preventDefault();
    if (!query.trim()) return;
    navigate(`/products?search=${encodeURIComponent(query.trim())}`);
  };

  return (
    <>
      <section className="home-hero">
        <div className="container hero-grid">
          <div className="hero-copy">
            <span className="eyebrow">Real-time product API integration</span>
            <h1 className="title">Search any tech product and fetch live product data automatically.</h1>
            <p className="subtitle">
              Tech Store now connects React, Node.js, MongoDB cache, external product APIs, and Python AI to show dynamic
              images, prices, descriptions, specs, ratings, availability, and recommendations.
            </p>
            <form className="hero-search" onSubmit={submit}>
              <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Try: RTX 5090 or MacBook Pro M5" />
              <button className="btn btn-primary" type="submit">Search APIs</button>
            </form>
            <div className="quick-searches">
              {quickSearches.map((item) => (
                <button key={item} onClick={() => navigate(`/products?search=${encodeURIComponent(item)}`)}>{item}</button>
              ))}
            </div>
            <div className="provider-row">
              {Object.entries(providerStatus || { dummyjson: true, bestbuy: false, ebay: false, serpapi: false }).map(([key, enabled]) => (
                <span className={`badge ${enabled ? 'provider-on' : 'provider-off'}`} key={key}>{enabled ? '●' : '○'} {key}</span>
              ))}
            </div>
          </div>
          <div className="hero-panel card">
            <div className="panel-top">AI Product Intelligence</div>
            <div className="panel-search-line">User searches “RTX 5090”</div>
            <div className="flow-step">React Search UI</div>
            <div className="flow-arrow">↓</div>
            <div className="flow-step">Node API Aggregator</div>
            <div className="flow-arrow">↓</div>
            <div className="flow-step">eBay · BestBuy · SerpAPI · DummyJSON</div>
            <div className="flow-arrow">↓</div>
            <div className="flow-step">MongoDB Cache + Python AI Ranking</div>
          </div>
        </div>
      </section>

      <section className="section">
        <div className="container">
          <div className="section-header">
            <div>
              <span className="eyebrow">Shop by category</span>
              <h2 className="title">Professional tech categories</h2>
            </div>
            <Link className="btn btn-secondary" to="/categories">View all</Link>
          </div>
          <div className="category-grid">
            {['Mobiles', 'Laptops', 'Computer Hardware', 'Gaming', 'Accessories', 'Smart Devices'].map((category) => (
              <Link className="category-tile card" to={`/products?category=${encodeURIComponent(category)}&search=${encodeURIComponent(category)}`} key={category}>
                <span>{category === 'Mobiles' ? '📱' : category === 'Laptops' ? '💻' : category === 'Gaming' ? '🎮' : category === 'Computer Hardware' ? '🧩' : category === 'Smart Devices' ? '⌚' : '🔌'}</span>
                <strong>{category}</strong>
                <small>Live API results</small>
              </Link>
            ))}
          </div>
        </div>
      </section>

      <section className="section">
        <div className="container">
          <div className="section-header">
            <div>
              <span className="eyebrow">AI trending products</span>
              <h2 className="title">Fetched dynamically from APIs</h2>
              <p className="subtitle">These cards are not manually stored. They are loaded from the backend product aggregation service.</p>
            </div>
            <Link className="btn btn-primary" to="/products?search=laptop">Open live search</Link>
          </div>
          <div className="grid grid-4">
            {trending.length === 0
              ? Array.from({ length: 4 }).map((_, index) => <div className="loading-skeleton" style={{ height: 320 }} key={index} />)
              : trending.map((product) => <ProductCard key={product.id || product.productId} product={product} />)}
          </div>
        </div>
      </section>
    </>
  );
}

export default Home;
